34	const BASE_PREMIUM: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	};
40	
41	const INSURANCE_VALUE: Record<string, number> = {
42	  sword: 1000,
43	  amulet: 600,
44	  staff: 800,
45	  potion: 400,
46	  rune: 250,
47	  moonstone: 250,
48	};
49	
50	const DEDUCTIBLE = 100;
51	const CAP_MULTIPLIER = 2;
52	
53	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	const LOYALTY_THRESHOLD = 2;
58	const LOYALTY_DISCOUNT_RATE = 0.2;
59	const FOLLOWUP_DISCOUNT_RATE = 0.15;
60	const PROCESSING_FEE = 5;
61	
62	const curseSurchargeFor = (item: Item): number =>
63	  item.cursed ? BASE_PREMIUM[item.type] * CURSE_SURCHARGE_RATE : 0;
64	
65	const highEnchantmentSurchargeFor = (item: Item): number =>
66	  item.enchantment !== undefined &&
67	  item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD
68	    ? BASE_PREMIUM[item.type] * HIGH_ENCHANTMENT_SURCHARGE_RATE
69	    : 0;
70	
71	const sumSurcharges = (
72	  items: Item[],
73	  surchargeFor: (item: Item) => number,
74	): number => items.reduce((sum, item) => sum + surchargeFor(item), 0);
75	
76	const COMPONENT_TYPES = ["rune", "moonstone"];
77	const COMPONENT_PREMIUM = 25;
78	const COMPONENT_BLOCK_SIZE = 3;
79	const COMPONENT_BLOCK_PREMIUM = 60;
80	
81	const isComponent = (item: { type: string }): boolean =>
82	  COMPONENT_TYPES.includes(item.type);
83	
84	const sumComponentPremium = (count: number): number =>
85	  count === COMPONENT_BLOCK_SIZE
86	    ? COMPONENT_BLOCK_PREMIUM
87	    : count * COMPONENT_PREMIUM;
88	
89	const countByType = (items: { type: string }[]): Map<string, number> => {
90	  const counts = new Map<string, number>();
91	  for (const item of items) {
92	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
93	  }
94	  return counts;
95	};
96	
97	const sumBasePremiums = (items: { type: string }[]): number => {
98	  let total = 0;
99	  for (const [type, count] of countByType(items)) {
100	    total += isComponent({ type })
101	      ? sumComponentPremium(count)
102	      : BASE_PREMIUM[type] * count;
103	  }
104	  return total;
105	};
106	
107	// Item-specific surcharges: each depends on a single item's attributes.
108	const itemSurchargesFor = (items: Item[]): number =>
109	  sumSurcharges(items, curseSurchargeFor) +
110	  sumSurcharges(items, highEnchantmentSurchargeFor);
111	
112	// Policy-wide adjustments: each is a rate applied to the whole policy base.
113	const policyAdjustmentsFor = (
114	  policyBase: number,
115	  customer: Customer,
116	  isFollowUp: boolean,
117	): number => {
118	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
119	  const loyaltyDiscount =
120	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD
121	      ? policyBase * LOYALTY_DISCOUNT_RATE
122	      : 0;
123	  const followUpDiscount = isFollowUp ? policyBase * FOLLOWUP_DISCOUNT_RATE : 0;
124	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
125	};
126	
127	const quotePremium = (
128	  step: QuoteStep,
129	  customer: Customer,
130	  isFollowUp: boolean,
131	): number => {
132	  const policyBase = sumBasePremiums(step.items);
133	  const premium =
134	    policyBase +
135	    itemSurchargesFor(step.items) +
136	    policyAdjustmentsFor(policyBase, customer, isFollowUp) +
137	    PROCESSING_FEE;
138	  return Math.ceil(premium);
139	};
140	
141	const insuranceSumOf = (items: Item[]): number =>
142	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
143	
144	const payoutForDamage = (damage: Damage): number =>
145	  Math.max(0, damage.amount - DEDUCTIBLE);
146	
147	const processClaim = (
148	  step: ClaimStep,
149	  policy: QuoteStep,
150	): { payout: number; remainingCap: number } => {
151	  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
152	  const payout = step.incident.damages.reduce(
153	    (sum, damage) => sum + payoutForDamage(damage),
154	    0,
155	  );
156	  return { payout, remainingCap: cap - payout };
157	};
