159	export const runScenario = (scenario: Scenario): unknown => {
160	  let quoteCount = 0;
161	  const results = scenario.steps.map((step) => {
162	    if (step.op === "quote") {
163	      const isFollowUp = quoteCount > 0;
164	      quoteCount += 1;
165	      return { premium: quotePremium(step, scenario.customer, isFollowUp) };
166	    }
167	    const policy = scenario.steps[step.policy] as QuoteStep;
168	    return processClaim(step, policy);
169	  });
170	  return { results };
171	};
