// Per-damage payout: reimbursable amount after the deductible.
// Takes the insured item so upcoming material/enchantment rules can adjust
// the reimbursed amount before the deductible is applied.
const payoutForDamage = (damage: Damage, insuredItem: Item): number => {
  const reimbursable = damage.amount;
  return Math.max(0, reimbursable - DEDUCTIBLE);
};

const insuredItemFor = (damage: Damage, policy: QuoteStep): Item =>
  policy.items.find((item) => item.type === damage.itemType) as Item;

const processClaim = (
  step: ClaimStep,
  policy: QuoteStep,
): { payout: number; remainingCap: number } => {
  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
  const payout = step.incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage, insuredItemFor(damage, policy)),
    0,
  );
  return { payout, remainingCap: cap - payout };
};

